//! Restart is inspection and exact repair, never a reconstructed producer.
use super::*;
// Same absolute record domain as StoreSelection::limits. Bootstrap is finite;
// every decoded original is then constrained by the selected store limit.
pub(super) const RECORD_CEILING:u64=1_048_576;
const ORIGINAL_COUNT:u64=23;
const REPAIR_COUNT:u64=12;
pub(super) const JOURNAL_CEILING:usize=4096;
pub(crate) fn journal_capacity(existing:usize,needed:usize)->Result<()>{require(existing.checked_add(needed).is_some_and(|n|n<=JOURNAL_CEILING),"PHYSICAL_JOURNAL_CAPACITY")}
use lab_completion_broker::{Frame,authority::{VerifiedDispatch,Decision,TrustDomain}};
use lab_control_store::ledger::{ReconcileAction,TrustedReconciliation};

