impl RepairKind {fn wire_action(self)->&'static str{match self{Self::SealObservedNew=>"complete_commit",Self::AbortOldCanonical=>"seal_outcome"}}}

/// An opaque proof carries only identities. It cannot produce Stage, authority,
/// disclosure permission, or a substitute for missing original records.
pub struct HistoryProof {pointer:Option<PointerRecord>,generation:String,terminal:Binding,retained_journals:BTreeMap<String,String>}
impl HistoryProof {pub fn pointer(&self)->Option<&PointerRecord>{self.pointer.as_ref()} pub fn terminal(&self)->&Binding{&self.terminal} pub fn generation(&self)->&str{&self.generation} pub(super) fn retained_journals(&self)->&BTreeMap<String,String>{&self.retained_journals}}

