        require(raw.keys().all(|n|allowed.contains(&n.as_str())||(1..=count).any(|p|*n==format!("phase-{p:02}.json"))),"RESTART_UNKNOWN_ORIGINAL")?;
        for n in [2,3,4]{if count>n{require(phase_rows[n].subject_binding.is_none(),"RESTART_PHASE_SUBJECT")?;}}
