        if let Some(value)=raw.get("member-manifest.json"){let native:MemberManifest=decode(value)?;require(manifest.member_manifest_binding.sha256==roots::hash(value)&&manifest.member_manifest_binding.size_bytes==value.len() as u64&&native.operation_id==operation.operation_id&&native.fingerprint==operation.fingerprint&&native.generation_name==manifest.generation_id&&native.stage_identity==manifest.stage_identity&&native.root_id==store.generations_root_id,"RESTART_MEMBER_MANIFEST")?;require(native.members.keys().cloned().collect::<BTreeSet<_>>()==manifest.members.keys().cloned().collect(),"RESTART_NATIVE_COVERAGE")?;for(path,b)in &manifest.members{let m=&native.members[path];require(b.sha256==m.sha256&&b.size_bytes==m.size_bytes,"RESTART_NATIVE_MEMBER")?;}}
