    fn guard(&self)->Result<()>{self.root.validate()?;self.journal.validate()?;control(self.held.nested())?;let named=roots::open_child(self.journal.directory(),&self.selection.journal_name,libc::O_RDONLY|libc::O_DIRECTORY,0,true)?;require(Identity::observe(&named)?==self.identity&&Identity::observe(&self.dir)?==self.identity&&roots::names(&self.dir,32)?==self.raw.keys().cloned().collect::<Vec<_>>(),"RESTART_ATTACHMENT")?;for(n,b)in &self.selection.originals{let f=roots::open_child(&self.dir,n,libc::O_RDONLY,0,true)?;require(self.files.get(n)==Some(&Identity::observe(&f)?)&&bytes(&self.dir,n,self.store.limits.max_record_bytes,self.identity.uid,self.identity.mount_id)?==self.raw[n]&&b.sha256==roots::hash(&self.raw[n]),"RESTART_ORIGINAL_CHANGED")?;}let present=roots::names(self.root.directory(),8193)?.contains(&self.store.pointer_member);require(present==self.pointer_identity.is_some(),"RESTART_POINTER_ATTACHMENT")?;if let Some(id)=&self.pointer_identity{let f=roots::open_child(self.root.directory(),&self.store.pointer_member,libc::O_RDONLY,0,true)?;require(Identity::observe(&f)?==*id&&self.selection.observed_pointer==Some(bind(&self.store.pointer_root_id,&self.store.pointer_member,&bytes(self.root.directory(),&self.store.pointer_member,self.store.limits.max_record_bytes,id.uid,id.mount_id)?)),"RESTART_POINTER_CHANGED")?;}self.validate_generation_if_present()}
