/// Accepted protocol verification is required for actual authority. Its current
/// host snapshot, revocation and once-only selection are fixed-loader duties;
/// no caller boolean or fixture constructor crosses that trust boundary.
pub struct RecoveryAuthority {domain:Domain,subject:Binding,wire:Binding,original:Vec<u8>,action:String,fingerprint:String,not_before:u64,expires:u64,scope:roots::ExecutionScope,operation:String}
impl RecoveryAuthority {
    pub(crate) fn check_time(&self,utc_ns:u64)->Result<()>{require(utc_ns<=i64::MAX as u64&&self.not_before<=utc_ns&&utc_ns<self.expires,"REPAIR_TIME_INTERVAL")}
    pub fn fixture(subject:Binding,kind:RepairKind,operation:&Operation,scope:roots::ExecutionScope,expires:u64)->Result<Self>{require(subject.valid()&&scope.valid()&&expires>0&&expires<=i64::MAX as u64&&roots::digest(&operation.fingerprint),"REPAIR_SUBJECT")?;let original=canonical(&serde_json::json!({"fixture_only":true,"subject":subject,"action":kind.wire_action(),"operation":operation,"scope":scope,"expires":expires}))?;require(original.len()<=65536,"REPAIR_WIRE_BOUND")?;Ok(Self{domain:Domain::Fixture,subject,wire:bind("fixture-authority","recovery-authorization.json",&original),original,action:kind.wire_action().into(),fingerprint:operation.fingerprint.clone(),not_before:0,expires,scope,operation:operation.operation_id.clone()})}
    pub fn from_verified(raw:&[u8],frame:&Frame,verified:&VerifiedDispatch,expected_original:Binding)->Result<Self>{
        require(raw.len()<=65536&&expected_original.valid()&&expected_original.sha256==roots::hash(raw)&&expected_original.size_bytes==raw.len() as u64&&roots::hash(raw)==frame.wire_digest()&&frame.wire_digest()==verified.wire_digest(),"REPAIR_WIRE")?;
        let decoded=Frame::decode(raw).map_err(|_|Error("REPAIR_FRAME"))?;require(decoded.request()==frame.request(),"REPAIR_FRAME")?;
        let v:serde_json::Value=serde_json::from_slice(raw).map_err(|_|Error("REPAIR_FRAME"))?;
        let (action,subject)=match verified.decision(){Decision::Recovery{action,subject_binding,..}=>(action.clone(),serde_json::from_value::<Binding>(subject_binding.clone()).map_err(|_|Error("REPAIR_SUBJECT"))?),_=>return Err(Error("RECOVERY_DECISION_REQUIRED"))};
        let r=frame.request();let scope=roots::ExecutionScope{activation_binding:serde_json::from_value(r["activation_binding"].clone()).map_err(|_|Error("REPAIR_SCOPE"))?,store_id:r["store_id"].as_str().ok_or(Error("REPAIR_SCOPE"))?.into(),instance_id:r["instance_id"].as_str().ok_or(Error("REPAIR_SCOPE"))?.into(),slot_epoch:r["slot_epoch"].as_u64().ok_or(Error("REPAIR_SCOPE"))?,principal_ref:r["principal_ref"].as_str().ok_or(Error("REPAIR_SCOPE"))?.into()};
        let to_ns=|field:&str|->Result<u64>{let seconds=v["permit"]["payload"][field].as_u64().ok_or(Error("REPAIR_TIME_DOMAIN"))?;let ns=seconds.checked_mul(1_000_000_000).ok_or(Error("REPAIR_TIME_OVERFLOW"))?;require(ns<=i64::MAX as u64,"REPAIR_TIME_OVERFLOW")?;Ok(ns)};
        let not_before=to_ns("not_before")?;let expires=to_ns("expires_at")?;require(not_before<expires,"REPAIR_TIME_INTERVAL")?;
        require(scope.valid()&&subject.valid()&&["complete_commit","seal_outcome"].contains(&action.as_str()),"REPAIR_SCOPE")?;
        Ok(Self{domain:match verified.trust_domain(){TrustDomain::Fixture=>Domain::Fixture,TrustDomain::Actual=>Domain::Actual},subject,wire:expected_original,original:raw.to_vec(),action,fingerprint:verified.operation_fingerprint().into(),not_before,expires,scope,operation:r["operation_id"].as_str().ok_or(Error("REPAIR_OPERATION"))?.into()})
    }
}
#[derive(Clone,Debug,Serialize,Deserialize)]
